function createLimiter(maxRequests) {
  let count = 0;
  return {
    tryRequest() {
      if (count >= maxRequests) return { allowed: false, count };
      count += 1;
      return { allowed: true, count };
    },
  };
}

async function runIsolated(maxRequests, callCount) {
  const calls = [];
  for (let i = 0; i < callCount; i++) {
    calls.push(Promise.resolve().then(() => createLimiter(maxRequests).tryRequest()));
  }
  const results = await Promise.all(calls);
  return results.filter((r) => r.allowed).length;
}

